code_sketch:
install(Authentication) {
    bearer("api") {                       // delegated mechanism
        authenticate { credential ->
            tokenStore.validate(credential.token)?.let { UserIdPrincipal(it) }
        }
    }
}
routing {
    get("/health") { call.respondText("ok") }        // explicit public route
    authenticate("api") {                            // enforcement point
        get("/orders") {
            val user = call.principal<UserIdPrincipal>() ?: error("missing principal")
            call.respond(ordersFor(user))
        }
    }
}
